	private class TestRootNode : GTreeNode {

		TestRootNode(int loadDelayMillis) {
			List<GTreeNode> newChildren = new();
			newChildren.add(new TestSlowLoadingNode(loadDelayMillis, 1));
			newChildren.add(new TestLeafNode());
			newChildren.add(new TestSlowLoadingNode(loadDelayMillis, 1));
