	private class TestSlowLoadingNode : GTreeSlowLoadingNode {

		private long loadDelayMillis;
		private int depth;

		TestSlowLoadingNode(long loadDelayMillis, int depth) {
			this.loadDelayMillis = loadDelayMillis;
			this.depth = depth;
		}

		/* @Override */
		public List<GTreeNode> generateChildren(TaskMonitor monitor)
    {

			if (depth > MAX_DEPTH) {
				return new();
			}

			monitor.checkCancelled();

			sleep(loadDelayMillis);

			while (pauseChildLoading) {
				sleep(100);
			}

			int childCount = getRandomInt(MIN_CHILD_COUNT, MAX_CHILD_COUNT);
			List<GTreeNode> newChildren = new();
			for (int i = 0; i < childCount; i++) {
				monitor.checkCancelled();
				int value = getRandomInt(0, 1);
				if (value == 0) {
					newChildren.add(new TestSlowLoadingNode(loadDelayMillis, depth + 1));
				}
				else {
					newChildren.add(new TestLeafNode());
				}
			}
			return newChildren;
		}

		/* @Override */
		public Icon getIcon(bool expanded) {
			return null;
		}

		/* @Override */
		public string getName() {
			return getClass().getSimpleName();
		}

		/* @Override */
		public string getToolTip() {
			return null;
		}

		/* @Override */
		public bool isLeaf() {
			return false;
		}

	}

